{
  "status": "STABLE",
  "core_findings": [
    "Training probes show positive separation across all four datasets: mean margins range from 4.39 to 7.49, with negatives outranking positives at 3.92–7.65% of supervised positions. Industrial_and_Scientific has the weakest separation, with a 0.484 lower-decile margin and 10.15% small-margin rate.",
    "Item representations retain substantial dimensional spread (RankMe 48.38–50.99), while appended-MASK user representations are more concentrated (21.53–32.47). Directional alignment alone does not establish collapse or recommendation diversity."
  ],
  "key_implications": [
    "Masked-target discrimination is working on the sampled training positions, but these probes do not establish validation HR@10.",
    "User representations occupy fewer effective dimensions than item embeddings, most noticeably in Industrial_and_Scientific; the measurements do not demonstrate collapse."
  ],
  "evidence": {
    "headline_metrics": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": 0.0392,
      "Industrial_and_Scientific:pos_neg_small_margin_rate": 0.1015,
      "Industrial_and_Scientific:real_items_rankme": 48.3847,
      "Industrial_and_Scientific:appended_mask_users_rankme": 21.5334
    },
    "brief_metric_read": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": "Lowest observed training wrong-rank rate.",
      "Industrial_and_Scientific:pos_neg_small_margin_rate": "Largest fraction of margins below 0.5.",
      "Industrial_and_Scientific:real_items_rankme": "Broad effective item dimensionality.",
      "Industrial_and_Scientific:appended_mask_users_rankme": "Lowest effective user dimensionality among the four datasets."
    }
  }
}
